// ==========================================
// Traffic Animation Engine
// ==========================================

console.log("Traffic Animation Engine Loaded");

// ==========================================
// Animation State
// ==========================================

let animationRunning = false;

// Generated by Packet Engine
let packetTasks = [];

// Active Packet
let packet = null;

// ==========================================
// Start Animation
// ==========================================

function startTrafficAnimation(graph) {

    animationRunning = true;

    // Build Packet Tasks from Graph
    packetTasks = buildPacketTasks(graph);

    console.log("Traffic Animation Started");

    console.table(packetTasks);

    // Remove previous packet
    removePacket();

    // Create new packet
    packet = createPacket();

    // Check if tasks exist
    if (packetTasks.length === 0) {

        console.warn("No Packet Tasks Found");

        return;

    }

    // Start Animation
    animatePacketTasks(packet);

}


// ==========================================
// Stop Animation
// ==========================================

function stopTrafficAnimation() {

    animationRunning = false;

    trafficPath = [];

    removePacket();

    console.log("Traffic Animation Stopped");

}

// ==========================================
// Create Packet
// ==========================================

function createPacket() {

    const packet = document.createElement("div");

    packet.className = "traffic-packet";

    packet.id = "trafficPacket";

    packet.style.left = "40px";

    packet.style.top = "40px";

    document
        .getElementById("designerCanvas")
        .appendChild(packet);

    return packet;

}

// ==========================================
// Remove Packet
// ==========================================

function removePacket() {

    const oldPacket =
        document.getElementById("trafficPacket");

    if (oldPacket) {

        oldPacket.remove();

    }

}

// ==========================================
// Move Packet To Node
// ==========================================

function movePacketToNode(packet, componentId) {

    return new Promise(resolve => {

        const position =
            getCanvasNodePosition(componentId);

        if (!position) {

            resolve();

            return;

        }

        packet.style.transition =
            "left 1s linear, top 1s linear";

        packet.style.left =
            position.x + "px";

        packet.style.top =
            position.y + "px";

        function finished() {

            packet.removeEventListener(
                "transitionend",
                finished
            );

            resolve();

        }

        packet.addEventListener(
            "transitionend",
            finished
        );

    });

}

// ==========================================
// Get Canvas Node Position
// ==========================================

function getCanvasNodePosition(componentId) {

    const node =
        document.getElementById(
            "component-" + componentId
        );

    if (!node) {

        console.warn(
            "Node Not Found :",
            componentId
        );

        return null;

    }

    const canvas =
        document.getElementById(
            "designerCanvas"
        );

    const nodeRect =
        node.getBoundingClientRect();

    const canvasRect =
        canvas.getBoundingClientRect();

    return {

        x:
            nodeRect.left
            - canvasRect.left
            + nodeRect.width / 2,

        y:
            nodeRect.top
            - canvasRect.top
            + nodeRect.height / 2

    };

}

// ==========================================
// Animate Packet Tasks
// ==========================================

async function animatePacketTasks(packet) {

    console.log("Animating Packet Tasks");

    for (const task of packetTasks) {

        if (!animationRunning) {

            break;

        }

        await movePacketToNode(
            packet,
            task.componentId
        );

    }

    console.log("Packet Animation Finished");

}
// ==========================================
// Pause Animation
// ==========================================

function pauseTrafficAnimation() {

    animationRunning = false;

}

// ==========================================
// Resume Animation
// ==========================================

function resumeTrafficAnimation() {

    animationRunning = true;

}

